// Imposta lo zoom/scala iniziale
vec2 z = (uv - 0.5) * 3.0; 

// Complex constant C (change these values to change the shape!)
// Interesting values: 
// vec2(-0.7, 0.27015)
// vec2(0.285, 0.01)
// vec2(-0.8, 0.156)
vec2 c = vec2(0.285, 0.01); 

int iter = 0;
int maxIter = 100;

// Iterazione Julia standard: Z = Z^2 + C
for(iter = 0; iter < maxIter; iter++) {
    float x = (z.x * z.x - z.y * z.y) + c.x;
    float y = (2.0 * z.x * z.y) + c.y;
    z = vec2(x, y);

    // If it leaves radius 2 (squared distance 4), it is outside the set
    if (dot(z, z) > 4.0) break;
}

// Colorazione
if (iter == maxIter) {
    // Inside the set: a dark but soft color (e.g. dark indigo)
    return vec3(0.2, 0.15, 0.3); 
} else {
    // Esterno: Gradiente Pastello
    float tit = float(iter) / 20.0; // Divisore più basso = bande più fitte

    // Generazione colori base (Ciclo RGB morbido)
    float r = 0.5 + 0.5 * cos(tit + 0.0);
    float g = 0.5 + 0.5 * cos(tit + 2.09); // 2.09 è circa 2*PI/3
    float b = 0.5 + 0.5 * cos(tit + 4.18); // 4.18 è circa 4*PI/3

    vec3 color = vec3(r, g, b);

    // PASTEL TRICK: 
    // We mix the color with white (vec3(1.0)) at 50%
    return mix(color, vec3(1.0), 0.5);
}
